function redKungfuRecord(id){return state.kungfu?.red?.[id]||{level:0,copies:0};}
function kungfuUsedBy(ref){for(const [heroId,h] of Object.entries(state.heroes)){const idx=h?.kungfu?.equipped?.indexOf(ref)??-1;if(idx>=0)return {heroId,index:idx};}return null;}
function kungfuNameFromRef(ref){if(!ref)return '空';if(String(ref).startsWith('god:'))return DIVINE_KUNGFU[String(ref).slice(4)]?.name||'神功';return RED_KUNGFU[ref]?.name||'功法';}
function kungfuEquipSlotsHtml(){
 const h=state.heroes[selectedGrowthHero],slots=kungfuSlotsForTalent(h.meridian?.talent||0),eq=h.kungfu?.equipped||[];
 return `<div class="kungfu-slots">${Array.from({length:8},(_,i)=>{const ref=eq[i],locked=i>=slots;return `<div class="kungfu-slot ${locked?'locked':''}"><div class="muted">第${i+1}槽${locked?' · 未解锁':''}</div><div class="hero-name">${locked?'—':kungfuNameFromRef(ref)}</div>${ref&&!locked?`<button class="btn btn-ghost btn-block" data-unequip-slot="${i}" style="margin-top:6px">卸下</button>`:''}</div>`;}).join('')}</div>`;
}
function redKungfuCards(){
 return Object.values(RED_KUNGFU).map(k=>{const rec=redKungfuRecord(k.id),owned=rec.level>0,used=kungfuUsedBy(k.id),need=owned&&rec.level<10?KUNGFU_UPGRADE_COPIES[rec.level]:0,canUpgrade=owned&&rec.level<10&&rec.copies>=need,canEquip=owned&&!used&&kungfuSlotsForTalent(state.heroes[selectedGrowthHero].meridian?.talent||0)>0;
 return `<div class="hero-card ${owned?'':'locked'}"><div class="hero-card-row"><div><div class="hero-name rarity-6">${k.name} ${owned?`Lv.${rec.level}`:'未获得'}</div><div class="hero-meta">${owned?displayEffect(k.id,rec.level):k.desc1}</div><div class="hero-meta">备用本体 ${fmt(rec.copies)}${used?` · 已装备：${HEROES[used.heroId]?.name||''}`:''}</div></div><div class="action-stack">${owned&&rec.level<10?`<button class="btn ${canUpgrade?'btn-primary':''}" data-upgrade-kungfu="${k.id}" ${canUpgrade?'':'disabled'}>升级 · ${need}本</button>`:''}${owned?`<button class="btn" data-equip-kungfu="${k.id}" ${canEquip?'':'disabled'}>${used?'已装备':'装备'}</button>`:''}</div></div></div>`;}).join('');
}
function divineCards(){
 return Object.values(DIVINE_KUNGFU).map(k=>{const owned=Number(state.kungfu?.divine?.[k.id]||0)>0,ref=`god:${k.id}`,used=kungfuUsedBy(ref),recipe=k.recipe||[],ready=recipe.every(r=>r.kind==='kungfu'?Number(state.kungfu?.red?.[r.id]?.level||0)>=10:Number(state.kungfu?.scrolls?.[r.id]||0)>=r.count),requirements=recipe.map(r=>r.kind==='kungfu'?`${r.name} Lv.10`:`${r.name}×${r.count}`).join(' + ');
 return `<div class="hero-card ${owned?'':'locked'}"><div class="hero-card-row"><div><div class="hero-name rarity-7">${k.name}</div><div class="hero-meta">${k.desc}</div><div class="hero-meta">融合：${requirements}</div></div><div class="action-stack">${owned?`<button class="btn btn-gold" data-equip-divine="${k.id}" ${used?'disabled':''}>${used?'已装备':'装备'}</button>`:`<button class="btn btn-gold" data-fuse-divine="${k.id}" ${ready?'':'disabled'}>融合</button>`}</div></div></div>`;}).join('');
}
function renderKungfuPanel(){
 const h=state.heroes[selectedGrowthHero],slots=kungfuSlotsForTalent(h.meridian?.talent||0);
 return `<section class="card"><div class="section-title"><h3>${HEROES[selectedGrowthHero].name} · 功法</h3><small>${slots}/8槽</small></div>${kungfuEquipSlotsHtml()}<div class="notice" style="margin-top:10px">功法槽由经脉天赋开启：220天赋一次开启前三槽，之后280/340/400/460/520依次开启。</div></section>
 <section class="card"><div class="section-title"><h3>藏经阁</h3><small>元宝直接抽取</small></div><div class="notice">300元宝抽1次，1500元宝抽5次。红色功法概率按当前原版元宝抽取的2%处理；低品质结果暂折算为功法残页。</div><div class="action-row" style="margin-top:10px"><button class="btn" data-action="drawKungfu1" ${state.player.gems<300?'disabled':''}>抽1次 · 300元宝</button><button class="btn btn-gold" data-action="drawKungfu5" ${state.player.gems<1500?'disabled':''}>抽5次 · 1500元宝</button></div><div class="hero-meta" style="margin-top:8px">累计抽取 ${fmt(state.kungfu?.drawCount||0)} 次 · 功法残页 ${fmt(state.kungfu?.fragments||0)}</div></section>
 <div class="section-title"><h3>红色功法</h3><small>25门</small></div><div class="hero-list">${redKungfuCards()}</div>
 <div class="section-title" style="margin-top:18px"><h3>神级融合功法</h3><small>13门</small></div><div class="hero-list">${divineCards()}</div>`;
}
function formatRemain(ms){const sec=Math.max(0,Math.ceil(ms/1000));if(sec<60)return `${sec}秒`;const min=Math.ceil(sec/60);if(min<60)return `${min}分钟`;return `${Math.floor(min/60)}小时${min%60?`${min%60}分钟`:''}`;}
function innerPowerRoomIndex(heroId){return (state.innerPower?.rooms||[]).indexOf(heroId);}
function renderInnerPowerPanel(){
 recoverInnerPower(state);
 const h=state.heroes[selectedGrowthHero],ip=h.innerPower||{year:0,power:0,recoveryUntil:0,passed:[],medicineUsed:{}},now=Date.now();
 const roomIndex=innerPowerRoomIndex(selectedGrowthHero),emptyRoom=(state.innerPower?.rooms||[]).findIndex(x=>!x),maxed=ip.year>=INNER_POWER_MAX_YEAR;
 const barrier=readyBreakthroughYear(ip),nextYear=maxed?INNER_POWER_MAX_YEAR:Math.min(INNER_POWER_MAX_YEAR,ip.year+1),currentReq=powerRequiredForYear(ip.year),nextReq=powerRequiredForYear(nextYear);
 const segment=Math.max(1,nextReq-currentReq),pct=maxed?100:Math.max(0,Math.min(100,Math.round((ip.power-currentReq)/segment*100)));
 const bInfo=barrier?breakthroughInfo(barrier):null,recoveryLeft=Math.max(0,Number(ip.recoveryUntil||0)-now);
 const milestones=innerPowerMilestones(selectedGrowthHero),unlocked=milestones.filter(x=>x.year<=ip.year),nextSkills=milestones.filter(x=>x.year>ip.year).slice(0,3);
 const rooms=(state.innerPower?.rooms||[]).map((heroId,i)=>`<div class="list-row"><span>${INNER_POWER_ROOM_NAMES[i]}</span><b>${heroId?(HEROES[heroId]?.name||'侠客'):'空闲'}</b></div>`).join('');
 const meds=Object.entries(INNER_POWER_MEDICINES).map(([key,m])=>{const count=Number(state.innerPower?.items?.[key]||0),used=Number(ip.medicineUsed?.[key]||0),ratio=Math.round(medicineRatio(used)*100),atCap=m.maxUses&&used>=m.maxUses,inRange=ip.year>=m.minYear&&ip.year<=m.maxYear&&!(m.kind==='power'&&maxed)&&!atCap;const effect=m.kind==='power'?`${innerMedicineEffectText(key,used)}（${ratio}%）`:innerMedicineEffectText(key,used);return `<div class="hero-card ${inRange&&count?'':'locked'}"><div class="hero-card-row"><div><div class="hero-name">${m.name} ×${fmt(count)}${m.v1?' <span class="tag">V1暂定</span>':''}</div><div class="hero-meta">适用 ${m.minYear}～${m.maxYear}年 · ${effect}</div></div><button class="btn" data-inner-medicine="${key}" ${inRange&&count?'':'disabled'}>服用</button></div></div>`;}).join('');
 const innerShop=Object.entries(INNER_POWER_SHOP).map(([key,cfg])=>{const m=INNER_POWER_MEDICINES[key],open=ip.year>=m.minYear,price=Number(cfg.price||0);return `<div class="list-row"><span>${m.name} <small>V1常驻迁移</small></span><button class="btn" data-buy-inner="${key}" ${open&&state.player.gems>=price?'':'disabled'}>${fmt(price)}元宝</button></div>`;}).join('');
 return `<section class="card"><div class="section-title"><h3>${HEROES[selectedGrowthHero].name} · 内力</h3><small>上限${INNER_POWER_MAX_YEAR}年</small></div><div class="big-number">${ip.year}年</div><div class="hero-meta">累计内力 ${fmt(ip.power)}${maxed?' · 已达上限':` · 下一年 ${fmt(nextReq)}`}</div><div class="progress" style="margin-top:10px"><i style="width:${pct}%"></i></div><div class="notice" style="margin-top:10px">练功房每分钟获得 ${INNER_POWER_PER_MINUTE} 内力；离线后再次打开游戏会按经过的完整分钟结算。</div></section>
 <section class="card"><div class="section-title"><h3>七大练功房</h3><small>${roomIndex>=0?`当前：${INNER_POWER_ROOM_NAMES[roomIndex]}`:'尚未入房'}</small></div>${rooms}<div class="action-row" style="margin-top:10px">${roomIndex>=0?`<button class="btn btn-danger" data-action="leaveInnerRoom">离开练功房</button>`:`<button class="btn btn-primary" data-action="assignInnerRoom" ${emptyRoom<0?'disabled':''}>进入空闲练功房</button>`}</div></section>
 ${barrier?`<section class="card"><div class="section-title"><h3>${barrier}年瓶颈</h3><small>基础成功率 ${(bInfo.rate*100).toFixed(1)}%</small></div>${recoveryLeft?`<div class="notice">突破失败后正在调息，还需 ${formatRemain(recoveryLeft)}。</div>`:`<div class="notice">突破成功后获得${barrier}年对应内力特性。失败后进入单机压缩调息：${formatRemain(bInfo.recoverySec*1000)}。</div><div class="action-row" style="margin-top:10px"><button class="btn btn-primary" data-action="innerBreakthrough">直接突破</button><button class="btn btn-gold" data-action="innerBreakthroughPill" ${Number(state.innerPower?.items?.dingshen||0)>0?'':'disabled'}>定神丸突破 · +${(calmingPillRateBonus(barrier)/100).toFixed(2)}%</button></div><div class="hero-meta" style="margin-top:8px">定神丸库存 ${fmt(state.innerPower?.items?.dingshen||0)}</div>`}</section>`:''}
 <section class="card"><div class="section-title"><h3>十年特性</h3><small>已解锁 ${unlocked.length}/28</small></div>${unlocked.length?`<div class="notice">最近获得：${unlocked.slice(-3).map(x=>`${x.year}年【${x.name}】${x.desc}`).join('；')}</div>`:'<div class="notice">达到10年并突破后获得第一项内力特性。</div>'}${nextSkills.map(x=>`<div class="list-row"><span>${x.year}年 · ${x.name}</span><small>${x.desc}</small></div>`).join('')}</section>
 <section class="card"><div class="section-title"><h3>内力丹药</h3><small>内力散递减 · 属性丹有上限</small></div><div class="hero-list">${meds}</div><div class="hero-meta" style="margin-top:8px">六类内力散沿用已确认数据；聚气丹、属性丹数值与投放为单机V1暂定，古墓为主产地，千宝塔节点与常驻元宝补充。</div></section><section class="card"><div class="section-title"><h3>内力常驻补给</h3><small>元宝迁移渠道</small></div>${innerShop}</section>`;
}
function weaponUsedBy(id){for(const [heroId,h] of Object.entries(state.heroes)){for(const [slot,wid] of Object.entries(h?.weapons||{}))if(wid===id)return {heroId,slot};}return null;}
function weaponSlotsHtml(){const eq=state.heroes[selectedGrowthHero].weapons||{};return `<div class="kungfu-slots">${Object.entries(WEAPON_TYPES).map(([slot,label])=>{const id=eq[slot],w=id?WEAPONS[id]:null;return `<div class="kungfu-slot"><div class="muted">${label}</div><div class="hero-name">${w?w.name:'空'}</div>${w?`<button class="btn btn-ghost btn-block" data-unequip-weapon="${slot}" style="margin-top:6px">卸下</button>`:''}</div>`;}).join('')}</div>`;}
function renderWeaponPanel(){
 const theme=Math.max(0,Math.min(FORGE_THEMES.length-1,Number(state.weapons?.theme||0))),t=FORGE_THEMES[theme],iron=Number(state.weapons?.iron||0),meteor=Number(state.weapons?.meteorIron||0),smeltOpen=state.player.level>=WEAPON_SMELT_OPEN_LEVEL;
 const cards=Object.values(WEAPONS).map(w=>{
  const r=weaponRecord(state,w.id),used=weaponUsedBy(w.id),need=r.breakthrough<5?breakthroughNeed(r.breakthrough):0,cost=strengthenCost(r.level),smelt=Math.max(0,Number(r.smelt||0)),sn=smelt<WEAPON_SMELT_MAX?smeltNeed(smelt):null;
  const canStr=r.owned&&r.level<WEAPON_MAX_LEVEL&&state.player.copper>=cost,canBreak=r.owned&&r.breakthrough<5&&r.copies>=need,canSmelt=r.owned&&smeltOpen&&r.breakthrough>=5&&smelt<WEAPON_SMELT_MAX&&r.copies>=sn.copies&&meteor>=sn.meteorIron;
  return `<div class="hero-card ${r.owned?'':'locked'}"><div class="hero-card-row"><div><div class="hero-name rarity-6">${w.name} ${r.owned?`强化+${r.level} · 突破${r.breakthrough} · 熔铸${smelt}火`:'未获得'}</div><div class="hero-meta">${WEAPON_TYPES[w.slot]} · ${w.effect}</div><div class="hero-meta">同名本体 ${fmt(r.copies)}${used?` · 已装备：${HEROES[used.heroId]?.name||''}`:''}</div>${r.owned?`<div class="hero-meta">熔铸属性：${smeltAttrText(state,w.id)}</div>`:''}</div><div class="action-stack">${r.owned?`<button class="btn ${canStr?'btn-primary':''}" data-strengthen-weapon="${w.id}" ${canStr?'':'disabled'}>强化 · ${fmt(cost)}铜钱</button><button class="btn ${canBreak?'btn-gold':''}" data-breakthrough-weapon="${w.id}" ${canBreak?'':'disabled'}>${r.breakthrough>=5?'已满突破':`突破 · ${need}本`}</button>${smelt<WEAPON_SMELT_MAX?`<button class="btn ${canSmelt?'btn-gold':''}" data-smelt-weapon="${w.id}" ${canSmelt?'':'disabled'}>熔铸${smelt+1}火 · ${sn.copies}本 + ${sn.meteorIron}陨铁</button>`:'<button class="btn btn-gold" disabled>熔铸3火圆满</button>'}<button class="btn" data-equip-weapon="${w.id}" ${used?.heroId===selectedGrowthHero?'disabled':''}>${used?.heroId===selectedGrowthHero?'已装备':'装备'}</button>`:''}</div></div></div>`;
 }).join('');
 return `<section class="card"><div class="section-title"><h3>${HEROES[selectedGrowthHero].name} · 神兵</h3><small>四部位</small></div>${weaponSlotsHtml()}<div class="notice" style="margin-top:10px">神兵培养：强化 + 突破1～5 + 熔铸1～3。原版熔铸需突破5且Lv.${WEAPON_SMELT_OPEN_LEVEL}开放；1/2/3火依次消耗同名本体5/10/15件与天外陨铁500/800/1200。</div></section>
 <section class="card"><div class="section-title"><h3>神兵锻造</h3><small>精铁 ${fmt(iron)} · 天外陨铁 ${fmt(meteor)}</small></div><div class="action-row">${FORGE_THEMES.map((x,i)=>`<button class="btn ${i===theme?'btn-gold':''}" data-weapon-theme="${i}">${x.name}</button>`).join('')}</div><div class="notice" style="margin-top:10px">当前主题：${t.name}。重点产出【${WEAPONS[t.featured].name}】，并可获得【${WEAPONS[t.secondary].name}】等神兵。</div><div class="action-row" style="margin-top:10px"><button class="btn" data-action="buyWeaponIron" ${state.player.gems<100?'disabled':''}>100元宝换100精铁</button><button class="btn" data-action="buyMeteorIron" ${state.player.gems<1000?'disabled':''}>1000元宝换100天外陨铁</button><button class="btn btn-primary" data-action="forgeWeapon" ${iron<WEAPON_FORGE_COST?'disabled':''}>锻造1次 · ${WEAPON_FORGE_COST}精铁</button></div><div class="hero-meta" style="margin-top:8px">精铁：千宝塔每10层+20。天外陨铁：千宝塔每100层+100；1000元宝换100陨铁为删去活动商店后的单机V1常驻迁移值，并非原版商店价格。</div></section>
 <div class="section-title"><h3>神兵库</h3><small>${Object.values(state.weapons?.items||{}).filter(x=>x.owned).length}/${Object.keys(WEAPONS).length}</small></div><div class="hero-list">${cards}</div>`;
}
function equipWeapon(id){ensureGrowthHero();const w=WEAPONS[id],r=weaponRecord(state,id);if(!w||!r.owned)return;for(const h of Object.values(state.heroes)){if(h?.weapons?.[w.slot]===id)h.weapons[w.slot]=null;}state.heroes[selectedGrowthHero].weapons[w.slot]=id;commit();}
function unequipWeapon(slot){ensureGrowthHero();if(state.heroes[selectedGrowthHero]?.weapons)state.heroes[selectedGrowthHero].weapons[slot]=null;commit();}
function strengthenWeapon(id){const r=weaponRecord(state,id);if(!r.owned||r.level>=WEAPON_MAX_LEVEL)return;const cost=strengthenCost(r.level);if(state.player.copper<cost)return alert(`铜钱不足，需要${fmt(cost)}。`);state.player.copper-=cost;r.level+=1;bumpDaily(state,'weapon');commit();}
function breakthroughWeapon(id){const r=weaponRecord(state,id);if(!r.owned||r.breakthrough>=5)return;const need=breakthroughNeed(r.breakthrough);if(r.copies<need)return alert(`同名神兵不足，需要${need}件。`);r.copies-=need;r.breakthrough+=1;commit();alert(`${WEAPONS[id].name}突破至${r.breakthrough}级。`);}
function smeltWeapon(id){const r=weaponRecord(state,id);if(!r.owned)return;if(state.player.level<WEAPON_SMELT_OPEN_LEVEL)return alert(`神兵熔铸需要玩家Lv.${WEAPON_SMELT_OPEN_LEVEL}。`);if(Number(r.breakthrough||0)<5)return alert('神兵突破5后才能熔铸。');const stage=Number(r.smelt||0);if(stage>=WEAPON_SMELT_MAX)return;const need=smeltNeed(stage),meteor=Number(state.weapons?.meteorIron||0);if(r.copies<need.copies)return alert(`同名神兵不足，需要${need.copies}件。`);if(meteor<need.meteorIron)return alert(`天外陨铁不足，需要${need.meteorIron}。`);r.copies-=need.copies;state.weapons.meteorIron=meteor-need.meteorIron;r.smelt=stage+1;bumpDaily(state,'weapon');commit();alert(`${WEAPONS[id].name}熔铸${r.smelt}火成功：${smeltAttrText(state,id)}`);}
function buyWeaponIron(){if(state.player.gems<100)return alert('元宝不足。');state.player.gems-=100;state.weapons.iron=Number(state.weapons.iron||0)+100;commit();}
function buyMeteorIron(){if(state.player.gems<1000)return alert('元宝不足。');state.player.gems-=1000;state.weapons.meteorIron=Number(state.weapons.meteorIron||0)+100;commit();}
function forgeWeapon(){if(Number(state.weapons?.iron||0)<WEAPON_FORGE_COST)return alert('精铁不足。');state.weapons.iron-=WEAPON_FORGE_COST;const id=rollForge(state.weapons.theme),r=weaponRecord(state,id);state.weapons.forgeCount=Number(state.weapons.forgeCount||0)+1;if(!r.owned){r.owned=true;r.level=1;}else r.copies+=1;commit();alert(`神兵锻造：获得【${WEAPONS[id].name}】${r.copies?`，当前备用本体${r.copies}件`:''}。`);}

function renderWudaoPanel(){const h=state.heroes[selectedGrowthHero],p=profileOf(selectedGrowthHero);ensureHeroWudao(h);const stage=wudaoStage(state,selectedGrowthHero),cost=nextWudaoCost(state,selectedGrowthHero),maxed=stage>=WUDAO_MAX_STAGE;const godReady=!!h.awakened||isStoryGod(state,selectedGrowthHero);return `<section class="card ${godReady?'':'locked'}"><div class="section-title"><h3>${p.name} · 悟道</h3><small>${stage}/${WUDAO_MAX_STAGE}阶</small></div><div class="grid-2"><div class="mini-stat"><div class="muted">悟道丹</div><div class="big-number small">${fmt(state.wudao?.pills||0)}</div></div><div class="mini-stat"><div class="muted">当前境界</div><div class="big-number small">${maxed?'返璞归真':`${stage}阶`}</div></div></div><div class="notice" style="margin-top:10px">${stage?wudaoStageText(selectedGrowthHero,stage):'神品觉醒后可开始悟道。悟道强化三维与角色核心机制。'}</div>${!maxed?`<div class="list-row" style="margin-top:10px"><span>下一阶：${wudaoStageText(selectedGrowthHero,stage+1)}</span><b>${fmt(cost)}悟道丹</b></div><button class="btn btn-gold btn-block" data-action="wudao" ${godReady&&Number(state.wudao?.pills||0)>=cost?'':'disabled'} style="margin-top:10px">悟道至${stage+1}阶</button>`:'<div class="battle-win" style="margin-top:12px">五阶悟道圆满</div>'}<div class="hero-meta" style="margin-top:8px">当前五阶消耗为单机V1暂定值，后续统一经济校准；不冒充原版精确消耗。</div></section>`;}
function advanceWudao(){ensureGrowthHero();const h=state.heroes[selectedGrowthHero];if(!h?.awakened&&!isStoryGod(state,selectedGrowthHero))return alert('只有神品侠客可以悟道。');ensureHeroWudao(h);const stage=wudaoStage(state,selectedGrowthHero);if(stage>=WUDAO_MAX_STAGE)return;const cost=nextWudaoCost(state,selectedGrowthHero);if(Number(state.wudao?.pills||0)<cost)return alert(`悟道丹不足，需要${cost}枚。`);state.wudao.pills-=cost;h.wudao.stage=stage+1;commit();alert(`${profileOf(selectedGrowthHero).name}悟道提升至${stage+1}阶。`);}

function renderGrowth(){ensureGrowthHero();const ownedIds=Object.keys(HEROES).filter(id=>state.heroes[id]?.owned);if(selectedGrowthTab==='innerPower'&&state.player.chapter<INNER_POWER_OPEN_CHAPTER)selectedGrowthTab='meridian';if(selectedGrowthTab==='weapons'&&state.player.level<WEAPON_OPEN_LEVEL)selectedGrowthTab='meridian';if(selectedGrowthTab==='wudao'&&!state.heroes[selectedGrowthHero]?.awakened&&!isStoryGod(state,selectedGrowthHero))selectedGrowthTab='meridian';const panel=selectedGrowthTab==='kungfu'?renderKungfuPanel():selectedGrowthTab==='innerPower'?renderInnerPowerPanel():selectedGrowthTab==='weapons'?renderWeaponPanel():selectedGrowthTab==='wudao'?renderWudaoPanel():renderMeridianPanel();pageEl.innerHTML=`<div class="section-title"><h2>养成</h2><small>经脉 · 功法 · 内力 · 神兵 · 悟道</small></div>${growthHeroSelector(ownedIds)}${growthTabs()}${panel}`;}

function grantWeaponCopies(id,count=1){const r=weaponRecord(state,id);let n=Math.max(0,Number(count)||0);if(!r.owned&&n>0){r.owned=true;r.level=1;n--;}r.copies=Number(r.copies||0)+n;}
function applyAncientTombReward(floor,firstClear=false){const r=rollAncientTombReward(floor,{firstClear});state.ancientTomb.materials=state.ancientTomb.materials||{};const parts=[];for(const [key,count] of Object.entries(r.materials)){state.ancientTomb.materials[key]=Number(state.ancientTomb.materials[key]||0)+count;parts.push(`${ANCIENT_TOMB_MATERIALS[key]} +${count}`);}state.innerPower.items[r.medicineKey]=Number(state.innerPower.items[r.medicineKey]||0)+r.medicineCount;parts.push(`${INNER_POWER_MEDICINES[r.medicineKey].name} +${r.medicineCount}`);if(r.calmingPills){state.innerPower.items.dingshen=Number(state.innerPower.items.dingshen||0)+r.calmingPills;parts.push(`定神丸 +${r.calmingPills}`);}if(r.speedTickets){state.ancientTomb.speedTickets=Number(state.ancientTomb.speedTickets||0)+r.speedTickets;parts.push(`古墓速战卷 +${r.speedTickets}`);}if(r.yuanyangCopies){grantWeaponCopies('yuanyang',r.yuanyangCopies);parts.push(`鸳鸯刀 +${r.yuanyangCopies}`);}if(r.soulChoicePacks){state.awakening.choicePacks=Number(state.awakening.choicePacks||0)+r.soulChoicePacks;parts.push(`神品魂石自选箱 +${r.soulChoicePacks}`);}if(r.wudaoPills){state.wudao.pills=Number(state.wudao.pills||0)+r.wudaoPills;parts.push(`悟道丹 +${r.wudaoPills}`);}for(const [key,count] of Object.entries(r.innerItems||{})){state.innerPower.items[key]=Number(state.innerPower.items[key]||0)+count;parts.push(`${INNER_POWER_MEDICINES[key]?.name||key} +${count}`);}const specialPack=tombSpecialChoicePack(floor,firstClear);if(specialPack){state.vipExtras.specialChoicePacks=Number(state.vipExtras.specialChoicePacks||0)+specialPack;parts.push(`奇侠兑换物自选包 +${specialPack}`);}return parts.join(' · ');}
function challengeAncientTomb(){if(state.player.chapter<ANCIENT_TOMB_OPEN_CHAPTER)return alert(`古墓奇遇第${ANCIENT_TOMB_OPEN_CHAPTER}幕开放。`);if(!hasParty())return alert('当前没有上阵侠客。');if(state.ancientTomb.highest>=ANCIENT_TOMB_MAX_FLOOR)return alert('古墓450层已经全部通关。');if(Number(state.ancientTomb.attemptsToday||0)<=0)return alert('今日古墓正式挑战次数已用完。');const floor=state.ancientTomb.highest+1,power=ancientTombPower(floor);state.ancientTomb.attemptsToday-=1;const result=runAncientTombBattle(state,floor,power);let reward='';if(result.win){state.ancientTomb.highest=floor;reward=applyAncientTombReward(floor,true);bumpDaily(state,'tomb');}commit();showBattle(result,`古墓奇遇 · ${floor}层`,reward);}
function speedAncientTomb(){if(state.player.chapter<ANCIENT_TOMB_OPEN_CHAPTER)return;if(state.ancientTomb.highest<=0)return alert('至少先通关古墓1层。');if(Number(state.ancientTomb.speedTickets||0)<=0)return alert('古墓速战卷不足。');state.ancientTomb.speedTickets-=1;const reward=applyAncientTombReward(state.ancientTomb.highest,false);bumpDaily(state,'tomb');commit();alert(`古墓速战完成：${reward}`);}
function renderAncientTombCard(){const t=state.ancientTomb||{},open=state.player.chapter>=ANCIENT_TOMB_OPEN_CHAPTER,done=Number(t.highest||0)>=ANCIENT_TOMB_MAX_FLOOR,next=Math.min(ANCIENT_TOMB_MAX_FLOOR,Number(t.highest||0)+1),power=ancientTombPower(next),materials=Object.entries(ANCIENT_TOMB_MATERIALS).map(([k,n])=>`${n}${fmt(t.materials?.[k]||0)}`).join(' · ');return `<section class="card ${open?'':'locked'}"><div class="section-title"><div><span class="tag">内力资源区</span><h3>古墓奇遇</h3></div><small>今日挑战 ${fmt(t.attemptsToday||0)}次</small></div><div class="big-number">${fmt(t.highest||0)}层</div><div class="muted">${done?'450层全部通关':`下一层 ${next} · 推荐战力约 ${fmt(power)}`}</div><div class="notice" style="margin-top:10px">六人单机挑战。主要产出内力药材、内力散、聚气丹与属性丹；30/50/100...450层首次到达可获得鸳鸯刀。聚气丹/属性丹投放为单机V1暂定值。</div><div class="hero-meta" style="margin-top:8px">药材：${materials}</div><div class="hero-meta">古墓速战卷 ${fmt(t.speedTickets||0)}</div><div class="action-row" style="margin-top:10px"><button class="btn btn-primary" data-action="ancientTomb" ${open&&!done&&Number(t.attemptsToday||0)>0?'':'disabled'}>${open?done?'已通关':`挑战${next}层`:`第${ANCIENT_TOMB_OPEN_CHAPTER}幕开放`}</button><button class="btn btn-gold" data-action="ancientTombSpeed" ${open&&Number(t.highest||0)>0&&Number(t.speedTickets||0)>0?'':'disabled'}>速战已通关层</button></div></section>`;}
function renderChallenge(){const next=state.tower.highest+1;pageEl.innerHTML=`<div class="section-title"><h2>挑战</h2><small>长期战力检验</small></div><section class="card"><span class="tag">永久爬塔</span><h3>少林千宝塔</h3><div class="big-number">${state.tower.highest}层</div><div class="muted">下一层：${next}层。按原版层数曲线产出经脉丹，每50层稳定获得突破丹。</div><button class="btn btn-primary btn-block" data-action="tower" style="margin-top:12px">挑战第${next}层</button></section>${renderAncientTombCard()}`;}
function soulStoreCard(id){const c=AWAKENINGS[id],h=state.heroes[id],frag=Number(state.awakening?.fragments?.[id]||0),stone=Number(state.awakening?.stones?.[id]||0),bought=Number(state.awakening?.shopBuys?.[id]||0),left=buyableShardPacks(state,id),open=state.player.chapter>=c.unlockChapter;return `<div class="hero-card ${open?'':'locked'}"><div class="hero-card-row"><div><div class="hero-name rarity-7">${c.godName}</div><div class="hero-meta">${h?.owned?'本体已拥有':'尚未获得本体'} · ${c.unlockChapter}幕觉醒 · 魂石ID ${c.soulId}</div><div class="hero-meta">碎片 ${fmt(frag)}/${SOUL_SHARDS_PER_STONE} · 魂石 ${fmt(stone)} · 常驻购买 ${bought}/${SOUL_SHARD_PACK_LIMIT}</div></div><div class="action-stack"><button class="btn" data-buy-soul="${id}" data-soul-times="1" ${open&&left>0&&state.player.gems>=SOUL_SHARD_PACK_PRICE?'':'disabled'}>40碎片 · ${SOUL_SHARD_PACK_PRICE}元宝</button><button class="btn" data-buy-soul="${id}" data-soul-times="5" ${open&&left>=5&&state.player.gems>=SOUL_SHARD_PACK_PRICE*5?'':'disabled'}>买5次</button>${Number(state.awakening?.choicePacks||0)>0?`<button class="btn" data-choice-soul="${id}">自选箱 +40</button>`:''}${frag>=SOUL_SHARDS_PER_STONE?`<button class="btn btn-gold" data-synth-soul="${id}">合成魂石</button>`:''}</div></div></div>`;}
function renderSoulStoneStore(){return `<section class="card"><div class="section-title"><h3>神品魂石商店</h3><small>自选箱 ${fmt(state.awakening?.choicePacks||0)}</small></div><div class="notice">单机常驻渠道：每次40碎片，25次正好1000碎片合成1枚魂石。当前价格1000元宝/40碎片属于单机版暂定经济值。千宝塔和古墓的高层节点会给魂石自选箱。</div><div class="hero-list" style="margin-top:10px">${Object.keys(AWAKENINGS).map(soulStoreCard).join('')}</div></section>`;}
function buySoulShards(id,times=1){const c=awakeningConfig(id);if(!c)return;const n=Math.max(1,Math.min(5,Number(times)||1)),left=buyableShardPacks(state,id),actual=Math.min(n,left);if(actual<=0)return alert('该魂石常驻购买次数已经用完。');if(state.player.chapter<c.unlockChapter)return alert(`第${c.unlockChapter}幕开放该神品魂石。`);const cost=actual*SOUL_SHARD_PACK_PRICE;if(state.player.gems<cost)return alert(`元宝不足，需要${fmt(cost)}。`);state.player.gems-=cost;state.awakening.shopBuys[id]=Number(state.awakening.shopBuys[id]||0)+actual;state.awakening.fragments[id]=Number(state.awakening.fragments[id]||0)+actual*SOUL_SHARD_PACK;commit();}
function useChoiceSoulPack(id){if(!awakeningConfig(id))return;if(Number(state.awakening?.choicePacks||0)<=0)return alert('魂石自选箱不足。');state.awakening.choicePacks-=1;state.awakening.fragments[id]=Number(state.awakening.fragments[id]||0)+SOUL_SHARD_PACK;commit();}
function synthSoul(id){if(!synthesizeSoulStone(state,id))return alert(`需要${SOUL_SHARDS_PER_STONE}魂石碎片。`);commit();alert(`已合成【${AWAKENINGS[id].godName}】对应魂石。`);}
function awakenHero(id){const c=awakeningConfig(id),h=state.heroes[id];if(!c||!h?.owned)return alert('尚未获得该侠客本体。');if(h.awakened)return;if(state.player.chapter<c.unlockChapter)return alert(`需要第${c.unlockChapter}幕。`);if(!canHeroAwaken(state,id))return alert('对应魂石不足。');state.awakening.stones[id]-=1;h.awakened=true;commit();alert(`觉醒成功：${c.godName}！`);}

function renderWudaoStore(){const pills=Number(state.wudao?.pills||0),limit=wudaoShopDailyLimit(state.player.vip),used=Number(state.daily?.wudaoShopBuys||0),packBuys=Number(state.wudao?.rechargePackBuys||0);return `<section class="card"><div class="section-title"><h3>悟道资源</h3><small>悟道丹 ${fmt(pills)}</small></div><div class="notice">正常渠道：千宝塔重要节点、古墓高层、元宝少量购买。VIP15不再锁死悟道，只把每日元宝购买上限从2次提高到5次。</div><div class="list-row" style="margin-top:10px"><div><b>悟道丹×${WUDAO_SHOP_PACK}</b><div class="hero-meta">今日 ${used}/${limit}</div></div><button class="btn" data-action="buyWudaoPills" ${used<limit&&state.player.gems>=WUDAO_SHOP_PRICE?'':'disabled'}>${WUDAO_SHOP_PRICE}元宝</button></div><div class="list-row"><div><b>648悟道礼包</b><div class="hero-meta">6480元宝 + 悟道丹${WUDAO_RECHARGE_PILLS} · ${packBuys}/${WUDAO_RECHARGE_LIMIT}</div></div><button class="btn btn-gold" data-action="wudaoRechargePack" ${packBuys<WUDAO_RECHARGE_LIMIT?'':'disabled'}>模拟648元</button></div></section>`;}
function buyWudaoPills(){const limit=wudaoShopDailyLimit(state.player.vip),used=Number(state.daily?.wudaoShopBuys||0);if(used>=limit)return alert('今日悟道丹元宝购买次数已用完。');if(state.player.gems<WUDAO_SHOP_PRICE)return alert('元宝不足。');state.player.gems-=WUDAO_SHOP_PRICE;state.daily.wudaoShopBuys=used+1;state.wudao.pills=Number(state.wudao.pills||0)+WUDAO_SHOP_PACK;commit();}
function buyWudaoRechargePack(){const used=Number(state.wudao?.rechargePackBuys||0);if(used>=WUDAO_RECHARGE_LIMIT)return alert('悟道礼包已达限购10次。');state.wudao.rechargePackBuys=used+1;state.player.totalRecharge+=WUDAO_RECHARGE_PRICE;state.player.gems+=WUDAO_RECHARGE_GEMS;state.wudao.pills=Number(state.wudao.pills||0)+WUDAO_RECHARGE_PILLS;recalcVip(state);commit();alert(`悟道礼包：元宝 +${fmt(WUDAO_RECHARGE_GEMS)}，悟道丹 +${WUDAO_RECHARGE_PILLS}。`);}

function claimActivityReward(threshold){ensureTaskState(state);const node=DAILY_ACTIVITY_REWARDS.find(x=>x.threshold===Number(threshold));if(!node)return;if(state.daily.activityClaimed.includes(node.threshold))return;if(dailyActivity(state)<node.threshold)return alert('今日活跃度还没达到这个档位。');grantTaskReward(state,node.reward);state.daily.activityClaimed.push(node.threshold);commit();alert(`活跃奖励领取：${taskRewardText(node.reward)}`);}
function claimGrowthTask(id){ensureTaskState(state);const task=GROWTH_TASKS.find(x=>x.id===id);if(!task||state.tasks.growthClaimed.includes(id))return;const progress=growthTaskProgress(state,task);if(progress<task.target)return alert('成长条件尚未完成。');state.tasks.growthClaimed.push(id);addPlayerExp(state,task.exp);commit();alert(`成长任务完成：玩家经验 +${fmt(task.exp)}。`);}
function renderDailyTasks(){ensureTaskState(state);const activity=dailyActivity(state),pct=Math.min(100,Math.round(activity/1000*100));const rows=DAILY_TASKS.map(t=>{const p=dailyTaskProgress(state,t),done=p>=t.target;return `<div class="list-row"><div><b>${t.name}</b><div class="hero-meta">${t.desc}</div></div><div style="text-align:right"><b>${Math.min(p,t.target)}/${t.target}</b><div class="hero-meta">${done?`已完成 · +${t.activity}活跃`:`+${t.activity}活跃`}</div></div></div>`;}).join('');const nodes=DAILY_ACTIVITY_REWARDS.map(n=>{const claimed=state.daily.activityClaimed.includes(n.threshold),can=activity>=n.threshold;return `<div class="list-row"><div><b>${n.threshold}活跃</b><div class="hero-meta">${taskRewardText(n.reward)}</div></div><button class="btn ${can&&!claimed?'btn-gold':''}" data-claim-activity="${n.threshold}" ${can&&!claimed?'':'disabled'}>${claimed?'已领取':'领取'}</button></div>`;}).join('');return `<section class="card"><div class="section-title"><h3>每日任务</h3><small>${Math.min(activity,1000)}/1000活跃</small></div><div class="progress"><i style="width:${pct}%"></i></div><div class="notice" style="margin-top:10px">11项任务每项130活跃，完成任意8项即可超过1000活跃，不要求全部清空。</div><div style="margin-top:8px">${rows}</div><div class="section-title" style="margin-top:12px"><h3>活跃奖励</h3><small>每日重置</small></div>${nodes}<div class="hero-meta" style="margin-top:8px">当前单项活跃值和宝箱具体资源为单机V1暂定配置，后续统一经济校准。</div></section>`;}
function renderGrowthTasks(){ensureTaskState(state);const claimed=new Set(state.tasks.growthClaimed||[]),left=GROWTH_TASKS.filter(t=>!claimed.has(t.id)),shown=left.slice(0,8),claimedCount=GROWTH_TASKS.length-left.length;const rows=shown.map(t=>{const p=growthTaskProgress(state,t),done=p>=t.target;return `<div class="list-row"><div><b>${t.name}</b><div class="hero-meta">${t.desc} · 玩家经验 +${fmt(t.exp)}</div></div><div style="text-align:right"><div class="hero-meta">${Math.min(p,t.target)}/${t.target}</div><button class="btn ${done?'btn-primary':''}" data-claim-growth="${t.id}" ${done?'':'disabled'}>领取</button></div></div>`;}).join('');return `<section class="card"><div class="section-title"><h3>成长任务</h3><small>${claimedCount}/${GROWTH_TASKS.length}</small></div><div class="notice">把原版绑定游历、战功、PVP等废系统的成长经验迁到现有核心玩法。18组任务合计约171.8万玩家经验。</div>${rows||'<div class="battle-win" style="margin-top:10px">当前18组成长任务已全部领取</div>'}${left.length>8?`<div class="hero-meta" style="margin-top:8px">完成/领取前面的任务后继续显示后续目标。</div>`:''}</section>`;}
function renderTaskCenter(){return `${renderDailyTasks()}${renderGrowthTasks()}`;}

function rechargeHtml(){return RECHARGE_PACKS.map(p=>{const first=!state.recharge.firstDoubleUsed[p.yuan],extra=p.yuan===6&&!state.recharge.first6Claimed?' · 首充小昭礼包':'';return `<button class="btn ${p.yuan===648?'btn-gold':''}" data-recharge="${p.yuan}">${p.yuan}元<br><small>${first?`首充 ${fmt(p.gems*2)}元宝`:`${fmt(p.gems+p.repeatBonus)}元宝`}${extra}</small></button>`;}).join('');}
function moneyTreeLimit(vip){if(vip>=10)return 50;if(vip>=8)return 40;if(vip>=6)return 30;if(vip>=4)return 20;if(vip>=2)return 15;return 10;}
function innRecruitRow(id){const tpl=HEROES[id],h=state.heroes[id],owned=!!h?.owned,open=state.player.chapter>=Number(tpl.unlock||0),r=tpl.recruit;if(!r)return '';let status='';if(owned)status='<span class="tag">已招募</span>';else if(!open)status=`<span class="muted">第${tpl.unlock}幕开放</span>`;else if(r.type==='legendToken')status=`<button class="btn ${state.player.legendTokens>=r.cost?'btn-primary':''}" data-recruit-hero="${id}" ${state.player.legendTokens>=r.cost?'':'disabled'}>${fmt(r.cost)}传奇令</button>`;else if(r.type==='special'){const have=Number(state.specials?.[r.item]||0);status=`<div style="text-align:right"><div class="hero-meta">${r.item} ${fmt(have)}/${fmt(r.cost)}</div><button class="btn ${have>=r.cost?'btn-gold':''}" data-recruit-hero="${id}" ${have>=r.cost?'':'disabled'}>兑换</button></div>`;}return `<div class="list-row"><div><b>${tpl.name}</b><div class="hero-meta">${r.type==='legendToken'?`第${tpl.unlock}幕 · ${fmt(r.cost)}传奇招募令`:`第${tpl.unlock}幕 · ${r.item}×${fmt(r.cost)}`}</div></div>${status}</div>`;}
function specialResourceRow(x){const have=Number(state.specials?.[x.item]||0),used=Number(state.vipExtras?.specialShopBuys?.[x.item]||0),packs=Number(state.vipExtras?.specialChoicePacks||0),open=state.player.chapter>=110;return `<div class="list-row"><div><b>${x.item}</b><div class="hero-meta">持有 ${fmt(have)} · 元宝限购 ${used}/${SPECIAL_ITEM_PACK_LIMIT}</div></div><div class="action-stack"><button class="btn" data-buy-special="${x.item}" ${open&&used<SPECIAL_ITEM_PACK_LIMIT&&state.player.gems>=SPECIAL_ITEM_PACK_PRICE?'':'disabled'}>${SPECIAL_ITEM_PACK_SIZE}个 · ${SPECIAL_ITEM_PACK_PRICE}元宝</button><button class="btn btn-gold" data-use-special-pack="${x.item}" ${open&&packs>0?'':'disabled'}>自选包 +${SPECIAL_ITEM_PACK_SIZE}</button></div></div>`;}
function renderInnCard(){return `<section class="card"><div class="section-title"><h3>客栈</h3><small>兑换 · 定向招募 · 奇侠兑换</small></div><div class="grid-2"><div class="mini-stat"><div class="muted">侠客信物</div><div class="big-number small">${fmt(state.player.heroTokens)}</div></div><div class="mini-stat"><div class="muted">传奇招募令</div><div class="big-number small">${fmt(state.player.legendTokens)}</div></div></div><div class="notice" style="margin-top:10px">侠客信物每10个兑换1次传奇招募令，保留1～15倍暴击。兑换出招募令后，不需要再去侠客页找入口，下面直接定向招募。</div><div class="action-row" style="margin-top:10px"><button class="btn btn-primary" data-exchange-legend="1" ${state.player.heroTokens<10?'disabled':''}>兑换1次</button><button class="btn btn-gold" data-exchange-legend="10" ${state.player.heroTokens<100?'disabled':''}>连续10次</button></div><div class="section-title" style="margin-top:14px"><h3>传奇定向招募</h3><small>达到幕数后常驻</small></div>${DIRECT_RECRUIT_IDS.map(innRecruitRow).join('')}<div class="section-title" style="margin-top:14px"><h3>奇侠兑换</h3><small>110幕档</small></div>${SPECIAL_EXCHANGE_IDS.map(innRecruitRow).join('')}<div class="section-title" style="margin-top:14px"><h3>奇侠专属物</h3><small>自选包 ${fmt(state.vipExtras?.specialChoicePacks||0)}</small></div><div class="notice">110幕后开放。专属物可元宝限购，也可从648模拟充值、千宝塔高层、古墓高层获得自选包。当前100个/1500元宝、每种限购10次属于单机V1暂定经济值。</div>${SPECIAL_EXCHANGE_ITEMS.map(specialResourceRow).join('')}</section>`;}
function vipGiftRow(g){const bought=!!state.recharge.vipGiftBought?.[g.vip],open=state.player.vip>=g.vip,can=open&&!bought&&state.player.gems>=g.price;return `<div class="list-row ${open?'':'locked'}"><div><b>VIP${g.vip}专属礼包</b><div class="hero-meta">${g.desc}</div></div><button class="btn ${can?'btn-gold':''}" data-buy-vip-gift="${g.vip}" ${can?'':'disabled'}>${bought?'已购买':open?(g.price?`${fmt(g.price)}元宝`:'免费领取'):`V${g.vip}解锁`}</button></div>`;}
function renderVipGiftCenter(){const ex=state.vipExtras||{};return `<section class="card"><div class="section-title"><h3>VIP专属礼包</h3><small>当前 V${state.player.vip}</small></div><div class="notice">达到对应VIP后仍需花元宝购买，不会自动发放。V8继续严格保留40888元宝购买黄衫女礼包。</div>${VIP_GIFTS.map(vipGiftRow).join('')}<div class="hero-meta" style="margin-top:8px">收藏：昆仑两仪剑×${fmt(ex.kunlunLiangyi||0)}${ex.skins?.length?` · 皮肤：${ex.skins.join('、')}`:''}${ex.titles?.length?` · 称号：${ex.titles.join('、')}`:''}${ex.frames?.length?` · 头像框：${ex.frames.join('、')}`:''}</div></section>`;}
function grantVipGiftReward(g){const r=g.reward||{};state.player.copper+=Number(r.copper||0);state.player.heroTokens+=Number(r.heroTokens||0);state.kungfu.fragments=Number(state.kungfu.fragments||0)+Number(r.kungfuFragments||0);state.vipExtras.kunlunLiangyi=Number(state.vipExtras.kunlunLiangyi||0)+Number(r.kunlun||0);for(const [id,n] of Object.entries(r.kungfu||{}))addKungfuCopy(id,n);if(r.hero){ownHero(state,r.hero);placeHeroIfPossible(r.hero);}if(r.skin&&!state.vipExtras.skins.includes(r.skin))state.vipExtras.skins.push(r.skin);if(r.title&&!state.vipExtras.titles.includes(r.title))state.vipExtras.titles.push(r.title);if(r.frame&&!state.vipExtras.frames.includes(r.frame))state.vipExtras.frames.push(r.frame);}
function buyVipGift(vip){const g=VIP_GIFTS.find(x=>x.vip===Number(vip));if(!g)return;if(state.player.vip<g.vip)return alert(`需要VIP${g.vip}。`);if(state.recharge.vipGiftBought[g.vip])return;if(state.player.gems<g.price)return alert(`元宝不足，需要${fmt(g.price)}。`);state.player.gems-=g.price;state.recharge.vipGiftBought[g.vip]=true;grantVipGiftReward(g);commit();alert(`VIP${g.vip}礼包购买成功：${g.desc}`);}
function buySpecialItem(item){const row=SPECIAL_EXCHANGE_ITEMS.find(x=>x.item===item);if(!row)return;if(state.player.chapter<110)return alert('奇侠专属物商店第110幕开放。');const used=Number(state.vipExtras.specialShopBuys[item]||0);if(used>=SPECIAL_ITEM_PACK_LIMIT)return alert('该专属物元宝限购已买满。');if(state.player.gems<SPECIAL_ITEM_PACK_PRICE)return alert('元宝不足。');state.player.gems-=SPECIAL_ITEM_PACK_PRICE;state.vipExtras.specialShopBuys[item]=used+1;state.specials[item]=Number(state.specials[item]||0)+SPECIAL_ITEM_PACK_SIZE;commit();}
function useSpecialChoicePack(item){if(state.player.chapter<110)return alert('奇侠专属物第110幕开放。');if(Number(state.vipExtras.specialChoicePacks||0)<=0)return alert('奇侠兑换物自选包不足。');if(!SPECIAL_EXCHANGE_ITEMS.some(x=>x.item===item))return;state.vipExtras.specialChoicePacks-=1;state.specials[item]=Number(state.specials[item]||0)+SPECIAL_ITEM_PACK_SIZE;commit();}

function renderMore(){const staminaLimit=STAMINA_BUY_LIMIT[state.player.vip]??24,staminaCost=staminaPrice(state.daily.staminaBuys),treeLimit=moneyTreeLimit(state.player.vip);pageEl.innerHTML=`<div class="section-title"><h2>更多</h2><small>任务 · 客栈 · 神品 · 充值 · 存档</small></div>${renderInnCard()}${renderTaskCenter()}${renderSoulStoneStore()}${renderWudaoStore()}<section class="card"><div class="section-title"><h3>模拟充值</h3><small>累计 ¥${fmt(state.player.totalRecharge)}</small></div><div class="notice">只修改本地存档，不产生真实支付。首充档位保留双倍元宝；648档额外获得1个奇侠兑换物自选包。</div><div class="grid-3" style="margin-top:10px">${rechargeHtml()}</div></section>${renderVipGiftCenter()}<section class="card"><div class="section-title"><h3>体力购买</h3><small>${state.daily.staminaBuys}/${staminaLimit}</small></div><div class="list-row"><span>每次 +25体力</span><button class="btn" data-action="buyStamina" ${state.daily.staminaBuys>=staminaLimit?'disabled':''}>${staminaCost}元宝</button></div></section><section class="card"><div class="section-title"><h3>摇钱树</h3><small>${state.daily.moneyTreeUses}/${treeLimit}</small></div><div class="muted">基础10万铜钱，有概率暴击至多倍。</div><button class="btn btn-gold btn-block" data-action="moneyTree" ${state.daily.moneyTreeUses>=treeLimit?'disabled':''} style="margin-top:10px">摇一次</button></section><section class="card"><div class="section-title"><h3>存档</h3><small>本地自动保存</small></div><div class="action-row"><button class="btn" data-action="export">导出JSON</button><button class="btn" data-action="import">导入JSON</button><button class="btn btn-danger" data-action="reset">重置存档</button></div></section>`;}

function render(){recoverStamina(state);recoverInnerPower(state);normalizeDaily(state);renderResources();document.querySelectorAll('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.page===currentPage));if(currentPage==='home')renderHome();if(currentPage==='heroes')renderHeroes();if(currentPage==='growth')renderGrowth();if(currentPage==='challenge')renderChallenge();if(currentPage==='more')renderMore();}
function showBattle(result,title,rewardText=''){battleDialogBody.innerHTML=`<div class="modal-inner"><div class="modal-head"><h3>${title}</h3><button class="btn btn-ghost" data-close-dialog>关闭</button></div><div class="${result.win?'battle-win':'battle-loss'}">${result.win?'胜利':'战败'} · 敌方战力约 ${fmt(result.enemyPower)}</div>${rewardText?`<div class="notice" style="margin:10px 0">${rewardText}</div>`:''}<div class="battle-log">${result.log.map(x=>`<div>${x}</div>`).join('')}</div></div>`;battleDialog.showModal();}
function hasParty(){return state.party.some(id=>id&&state.heroes[id]?.owned);}
function challengeChapter(){if(!hasParty())return alert('当前没有上阵侠客。');const need=requiredPlayerLevelForChapter(state.player.chapter);if(state.player.level<need)return alert(`等级不足：第${state.player.chapter}幕需要 Lv.${need}。先速战获取经验。`);const chapter=state.player.chapter,result=runChapterBattle(state);let reward='';if(result.win){const exp=180+chapter*36,copper=12000+chapter*1800,heroExp=800+chapter*80;addPlayerExp(state,exp);state.player.copper+=copper;state.player.heroExp=Number(state.player.heroExp||0)+heroExp;state.player.heroTokens+=chapter%5===0?2:0;state.player.chapter+=1;reward=`玩家经验 +${fmt(exp)} · 侠客经验 +${fmt(heroExp)} · 铜钱 +${fmt(copper)}${chapter%5===0?' · 侠客信物 +2':''}`;const story=storyMilestonesAtChapter(state.player.chapter);if(story.length)reward+=` · 剧情觉醒：${story.map(x=>`${x.heroId==='player'?'少侠':'张无忌'}【${x.title}】`).join('、')}`;commit();}showBattle(result,`主线 · 第${chapter}幕`,reward);}
function quickBattle(){const times=5,cost=times*5;if(state.player.stamina<cost)return alert(`体力不足，连续速战5次需要${cost}体力。`);state.player.stamina-=cost;state.daily.quickBattles+=times;const oneExp=260+state.player.chapter*44,oneCopper=10000+state.player.chapter*900,oneHeroExp=1800+state.player.chapter*120,exp=oneExp*times,copper=oneCopper*times,heroExp=oneHeroExp*times;addPlayerExp(state,exp);state.player.copper+=copper;state.player.heroExp=Number(state.player.heroExp||0)+heroExp;commit();alert(`连续速战5次完成：玩家经验 +${fmt(exp)}，侠客经验 +${fmt(heroExp)}，铜钱 +${fmt(copper)}，体力 -${cost}。`);}
function towerBaseMeridianPills(floor){if(floor<=100)return 2;if(floor<=150)return 3;if(floor<=200)return 4;if(floor<=250)return 5;if(floor<=300)return 6;if(floor<=350)return 8;return 10;}
function towerMilestoneReward(floor){let meridian=0,breakthrough=0,mixedYiqi=0;if(floor===3)meridian+=20;if(floor%10===0){const tier=Math.min(200,10*(Math.floor(floor/100)+1));if(floor%50===0)breakthrough+=Math.min(100,tier);else meridian+=tier;}if(floor%500===0)mixedYiqi=floor===2500?2:1;return {meridian,breakthrough,mixedYiqi};}
function addKungfuCopy(id,count=1){const rec=state.kungfu.red[id];if(!rec)return;let n=Math.max(0,Number(count)||0);if(rec.level<=0&&n>0){rec.level=1;n--;}rec.copies+=n;}
function challengeTower(){if(!hasParty())return alert('当前没有上阵侠客。');const result=runTowerBattle(state);let reward='';if(result.win){state.tower.highest=result.floor;const basePills=towerBaseMeridianPills(result.floor),milestone=towerMilestoneReward(result.floor),pills=basePills+milestone.meridian,copper=8000+result.floor*1200,iron=result.floor%10===0?20:0,meteorIron=result.floor%100===0?100:0;state.player.meridianPills+=pills;state.weapons.iron=Number(state.weapons.iron||0)+iron;state.weapons.meteorIron=Number(state.weapons.meteorIron||0)+meteorIron;state.player.breakthroughPills+=milestone.breakthrough;state.player.copper+=copper;if(milestone.mixedYiqi)addKungfuCopy('105701',milestone.mixedYiqi);if(result.floor%100===0){state.awakening.choicePacks=Number(state.awakening.choicePacks||0)+1;state.innerPower.items.juqi=Number(state.innerPower.items.juqi||0)+1;}const v1TowerAttr=result.floor%250===0?['qiangjin','tongpi','huoxue','atkdan','defdan','hpdan','critdan','hitdan','dodgedan','anticritdan'][Math.floor(result.floor/250-1)%10]:'';if(v1TowerAttr)state.innerPower.items[v1TowerAttr]=Number(state.innerPower.items[v1TowerAttr]||0)+1;const wudaoGain=result.floor>=250&&result.floor%250===0?20+Math.floor(result.floor/250)*5:0;if(wudaoGain)state.wudao.pills=Number(state.wudao.pills||0)+wudaoGain;const specialPack=towerSpecialChoicePack(result.floor);if(specialPack)state.vipExtras.specialChoicePacks=Number(state.vipExtras.specialChoicePacks||0)+specialPack;reward=`经脉丹 +${pills} · 铜钱 +${fmt(copper)}`;if(milestone.breakthrough)reward+=` · 突破丹 +${milestone.breakthrough}`;if(milestone.mixedYiqi)reward+=` · 混元一气功 +${milestone.mixedYiqi}`;if(iron)reward+=` · 精铁 +${iron}`;if(meteorIron)reward+=` · 天外陨铁 +${meteorIron}`;if(result.floor%100===0)reward+=` · 神品魂石自选箱 +1 · 聚气丹 +1`;if(v1TowerAttr)reward+=` · ${INNER_POWER_MEDICINES[v1TowerAttr].name} +1`;if(wudaoGain)reward+=` · 悟道丹 +${wudaoGain}`;if(specialPack)reward+=` · 奇侠兑换物自选包 +${specialPack}`;bumpDaily(state,'tower');commit();}showBattle(result,`少林千宝塔 · ${result.floor}层`,reward);}
function heroExpLevelCost(level){const lv=Math.max(1,Number(level)||1);return Math.round(1000+Math.pow(lv,1.22)*280);}
function levelHero(id){const h=state.heroes[id];if(!h?.owned)return;if(h.level>=state.player.level)return alert('侠客等级不能超过玩家等级。');const cost=Math.round(3000*Math.pow(1.09,h.level-1)),expCost=heroExpLevelCost(h.level);if(state.player.copper<cost)return alert(`铜钱不足，需要 ${fmt(cost)}。`);if(Number(state.player.heroExp||0)<expCost)return alert(`侠客经验不足，需要 ${fmt(expCost)}。主线与速战可获得。`);state.player.copper-=cost;state.player.heroExp-=expCost;h.level+=1;bumpDaily(state,'hero');commit();}
function placeHeroIfPossible(id){if(state.party.includes(id))return true;const empty=state.party.findIndex(x=>!x);if(empty<0)return false;state.party[empty]=id;return true;}
function togglePartyHero(id){const h=state.heroes[id];if(!h?.owned)return;const index=state.party.indexOf(id);if(index>=0){if(state.party.filter(Boolean).length<=1)return alert('阵容至少保留1名侠客。');state.party[index]=null;commit();return;}if(!placeHeroIfPossible(id))return alert('阵容已满6人，请先下阵一名侠客。');commit();}
function rollLegendMultiplier(){let roll=Math.floor(Math.random()*10000)+1;for(const [multi,weight] of LEGEND_EXCHANGE_WEIGHTS){roll-=weight;if(roll<=0)return multi;}return 1;}
function exchangeLegendTokens(times=1){const count=Math.max(1,Math.min(100,Number(times)||1)),maxByTokens=Math.floor(state.player.heroTokens/10),actual=Math.min(count,maxByTokens);if(actual<=0)return alert('侠客信物不足，每次需要10个。');state.player.heroTokens-=actual*10;let gained=0;const details=[];for(let i=0;i<actual;i++){const multi=rollLegendMultiplier();gained+=multi;details.push(`×${multi}`);}state.player.legendTokens+=gained;bumpDaily(state,'inn',actual);commit();alert(`客栈兑换${actual}次：获得传奇招募令 ${gained} 个。\n倍率：${details.join('、')}`);}
function recruitHero(id){const tpl=HEROES[id],h=state.heroes[id];if(!tpl||!h||h.owned)return;if(state.player.chapter<(tpl.unlock||0))return alert(`需要推进到第${tpl.unlock}幕。`);const recruit=tpl.recruit;if(!recruit)return alert('该侠客当前不是客栈招募侠客。');if(recruit.type==='legendToken'){if(state.player.legendTokens<recruit.cost)return alert(`传奇招募令不足，需要${recruit.cost}。`);state.player.legendTokens-=recruit.cost;}else if(recruit.type==='special'){const have=Number(state.specials?.[recruit.item]||0);if(have<recruit.cost)return alert(`${recruit.item}不足，需要${recruit.cost}。`);state.specials[recruit.item]=have-recruit.cost;}else return alert('该侠客需要通过专属途径获得。');ownHero(state,id);placeHeroIfPossible(id);commit();alert(`${tpl.name}已加入侠客列表。`);}
function unlockMeridianPoint(){ensureGrowthHero();const h=state.heroes[selectedGrowthHero];if(!h?.owned)return;const m=h.meridian||(h.meridian={progress:0,atk:0,def:0,hp:0,talent:0});if(m.progress>=MERIDIAN_TOTAL_POINTS)return alert('该侠客十三经脉已经全部圆满。');const point=getMeridianPoint(m.progress);if(point.requiredLevel&&state.player.level<point.requiredLevel)return alert(`等级不足，需要玩家Lv.${point.requiredLevel}。`);if(state.player.meridianPills<point.meridianPills)return alert(`经脉丹不足，需要${point.meridianPills}。`);if(state.player.breakthroughPills<point.breakthroughPills)return alert(`突破丹不足，需要${point.breakthroughPills}。`);state.player.meridianPills-=point.meridianPills;state.player.breakthroughPills-=point.breakthroughPills;m.atk=Number(m.atk||0)+point.atk;m.def=Number(m.def||0)+point.def;m.hp=Number(m.hp||0)+point.hp;m.talent=Number(m.talent||0)+point.talent;m.progress=Number(m.progress||0)+1;bumpDaily(state,'meridian');commit();}
function firstOpenKungfuSlot(heroId){const h=state.heroes[heroId],slots=kungfuSlotsForTalent(h.meridian?.talent||0),eq=h.kungfu.equipped;for(let i=0;i<slots;i++)if(!eq[i])return i;return -1;}
function equipKungfuRef(ref){ensureGrowthHero();if(kungfuUsedBy(ref))return alert('这门功法已经装备在其他侠客身上。');const slot=firstOpenKungfuSlot(selectedGrowthHero);if(slot<0)return alert('当前没有空闲的已解锁功法槽。');state.heroes[selectedGrowthHero].kungfu.equipped[slot]=ref;commit();}
function unequipSlot(index){const h=state.heroes[selectedGrowthHero],i=Number(index);if(!h?.kungfu?.equipped?.[i])return;h.kungfu.equipped[i]=null;commit();}
function upgradeKungfu(id){const rec=state.kungfu.red[id];if(!rec||rec.level<=0||rec.level>=10)return;const need=KUNGFU_UPGRADE_COPIES[rec.level];if(rec.copies<need)return alert(`同名本体不足，需要${need}本。`);rec.copies-=need;rec.level+=1;bumpDaily(state,'kungfu');commit();}
function drawKungfu(times=1){const n=Number(times)===5?5:1,cost=n*300;if(state.player.gems<cost)return alert(`元宝不足，需要${cost}元宝。`);state.player.gems-=cost;const reds=[];let fragments=0;for(let i=0;i<n;i++){state.kungfu.drawCount=Number(state.kungfu.drawCount||0)+1;if(Math.random()<.02){const ids=Object.keys(RED_KUNGFU),id=ids[Math.floor(Math.random()*ids.length)];addKungfuCopy(id,1);reds.push(RED_KUNGFU[id].name);}else{state.kungfu.fragments=Number(state.kungfu.fragments||0)+1;fragments++;}}bumpDaily(state,'scripture',n);commit();const redText=reds.length?`红色功法：${reds.map(x=>`【${x}】`).join('、')}`:'未获得红色功法';alert(`藏经阁抽取${n}次：${redText}${fragments?`；功法残页 +${fragments}`:''}。`);}
function removeKungfuEverywhere(ref){for(const h of Object.values(state.heroes)){if(!h?.kungfu?.equipped)continue;h.kungfu.equipped=h.kungfu.equipped.map(x=>x===ref?null:x);}}
function fuseDivine(id){const k=DIVINE_KUNGFU[id];if(!k||state.kungfu.divine[id])return;for(const r of k.recipe){if(r.kind==='kungfu'){if(Number(state.kungfu.red[r.id]?.level||0)<10)return alert(`${r.name}尚未满级。`);}else if(Number(state.kungfu.scrolls[r.id]||0)<r.count)return alert(`${r.name}不足。`);}for(const r of k.recipe){if(r.kind==='kungfu'){removeKungfuEverywhere(r.id);state.kungfu.red[r.id]={level:0,copies:0};}else state.kungfu.scrolls[r.id]-=r.count;}state.kungfu.divine[id]=1;commit();alert(`融合成功：${k.name}`);}
function assignInnerRoom(){if(state.player.chapter<INNER_POWER_OPEN_CHAPTER)return alert(`内力系统第${INNER_POWER_OPEN_CHAPTER}幕开放。`);ensureGrowthHero();if(innerPowerRoomIndex(selectedGrowthHero)>=0)return;const index=(state.innerPower?.rooms||[]).findIndex(x=>!x);if(index<0)return alert('七个练功房都有人。');state.innerPower.rooms[index]=selectedGrowthHero;state.innerPower.lastTick=Date.now();commit();}
function leaveInnerRoom(){ensureGrowthHero();recoverInnerPower(state);const index=innerPowerRoomIndex(selectedGrowthHero);if(index<0)return;state.innerPower.rooms[index]=null;state.innerPower.lastTick=Date.now();commit();}
function useInnerMedicine(key){ensureGrowthHero();const m=INNER_POWER_MEDICINES[key],h=state.heroes[selectedGrowthHero],ip=h?.innerPower;if(!m||!ip)return;const count=Number(state.innerPower?.items?.[key]||0);if(count<=0)return alert(`${m.name}不足。`);if(ip.year<m.minYear||ip.year>m.maxYear)return alert(`${m.name}仅适用于${m.minYear}～${m.maxYear}年。`);if(m.kind==='power'&&ip.year>=INNER_POWER_MAX_YEAR)return alert('内力已经达到280年上限。');const used=Number(ip.medicineUsed?.[key]||0);if(m.maxUses&&used>=m.maxUses)return alert(`${m.name}已达到单侠客服用上限${m.maxUses}次。`);const gain=medicinePower(key,used);state.innerPower.items[key]-=1;ip.medicineUsed[key]=used+1;if(gain){ip.power=Number(ip.power||0)+gain;advanceInnerPower(ip);}bumpDaily(state,'inner');const text=m.kind==='power'?`内力 +${fmt(gain)}`:innerMedicineEffectText(key,used+1);commit();alert(`${HEROES[selectedGrowthHero].name}服用${m.name}：${text}。`);}
function buyInnerItem(key){const m=INNER_POWER_MEDICINES[key],cfg=INNER_POWER_SHOP[key];if(!m||!cfg)return;ensureGrowthHero();const ip=state.heroes[selectedGrowthHero]?.innerPower;if(!ip||ip.year<m.minYear)return alert(`${m.name}需要内力达到${m.minYear}年后购买。`);const price=Number(cfg.price||0);if(state.player.gems<price)return alert(`元宝不足，需要${price}。`);state.player.gems-=price;state.innerPower.items[key]=Number(state.innerPower.items[key]||0)+1;commit();}
function attemptInnerBreakthrough(usePill=false){ensureGrowthHero();const ip=state.heroes[selectedGrowthHero]?.innerPower;if(!ip)return;const year=readyBreakthroughYear(ip);if(!year)return alert('当前尚未到十年瓶颈。');const now=Date.now();if(Number(ip.recoveryUntil||0)>now)return alert(`仍在调息，还需${formatRemain(ip.recoveryUntil-now)}。`);bumpDaily(state,'inner');const info=breakthroughInfo(year);let rate=info.rateBp;if(usePill){if(Number(state.innerPower?.items?.dingshen||0)<=0)return alert('定神丸不足。');state.innerPower.items.dingshen-=1;rate+=calmingPillRateBonus(year);}rate=Math.min(10000,rate);if(Math.floor(Math.random()*10000)<rate){ip.passed=Array.isArray(ip.passed)?ip.passed:[];if(!ip.passed.includes(year))ip.passed.push(year);ip.year=year;ip.recoveryUntil=0;advanceInnerPower(ip);commit();alert(`突破成功！${HEROES[selectedGrowthHero].name}内力达到${year}年。`);}else{ip.recoveryUntil=Date.now()+info.recoverySec*1000;commit();alert(`突破失败，进入调息 ${formatRemain(info.recoverySec*1000)}。`);}}
function recharge(yuan){const pack=RECHARGE_PACKS.find(x=>x.yuan===yuan);if(!pack)return;const first=!state.recharge.firstDoubleUsed[yuan],first6=yuan===6&&!state.recharge.first6Claimed,gained=first?pack.gems*2:pack.gems+pack.repeatBonus;state.recharge.firstDoubleUsed[yuan]=true;state.player.totalRecharge+=yuan;state.player.gems+=gained;let extra='';if(first6){state.recharge.first6Claimed=true;state.player.gems+=60;state.player.heroExp=Number(state.player.heroExp||0)+10000;ownHero(state,'xiaozhao');placeHeroIfPossible('xiaozhao');extra+='。首充礼包额外60元宝、小昭、侠客经验10000';}if(yuan===648){state.vipExtras.specialChoicePacks=Number(state.vipExtras.specialChoicePacks||0)+1;extra+='。奇侠兑换物自选包 +1';}recalcVip(state);commit();alert(`模拟充值 ¥${yuan}：获得 ${fmt(gained)} 元宝${extra||'。'}`);}
function buyStamina(){const limit=STAMINA_BUY_LIMIT[state.player.vip]??24;if(state.daily.staminaBuys>=limit)return alert('今日体力购买次数已用完。');const price=staminaPrice(state.daily.staminaBuys);if(state.player.gems<price)return alert('元宝不足。');state.player.gems-=price;state.player.stamina+=25;state.daily.staminaBuys+=1;commit();}
function moneyTreeCost(){const n=state.daily.moneyTreeUses+1;if(n===1)return 0;if(n<=3)return 50;if(n<=5)return 60;if(n<=7)return 70;if(n<=9)return 80;if(n<=11)return 90;return 100;}
function moneyTree(){const limit=moneyTreeLimit(state.player.vip);if(state.daily.moneyTreeUses>=limit)return alert('今日摇钱树次数已用完。');const cost=moneyTreeCost();if(state.player.gems<cost)return alert('元宝不足。');state.player.gems-=cost;state.daily.moneyTreeUses+=1;const r=Math.random(),multi=r<.015?5:r<.06?3:r<.20?2:1,gain=100000*multi;state.player.copper+=gain;commit();alert(`摇钱树${multi>1?`暴击×${multi}`:''}：铜钱 +${fmt(gain)}。`);}
async function onImport(file){if(!file)return;try{state=await importSaveFile(file);ensureGrowthHero();commit();alert('存档导入成功。');}catch(err){alert(`导入失败：${err.message}`);}finally{importInput.value='';}}

pageEl.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.pageJump){currentPage=btn.dataset.pageJump;render();return;}if(btn.dataset.heroFilter){heroFilter=btn.dataset.heroFilter;heroDetailId=null;renderHeroes();return;}if(btn.dataset.heroDetail){heroDetailId=heroDetailId===btn.dataset.heroDetail?null:btn.dataset.heroDetail;renderHeroes();return;}if(btn.dataset.growthTab){selectedGrowthTab=btn.dataset.growthTab;renderGrowth();return;}if(btn.dataset.levelHero){levelHero(btn.dataset.levelHero);return;}if(btn.dataset.toggleParty){togglePartyHero(btn.dataset.toggleParty);return;}if(btn.dataset.recruitHero){recruitHero(btn.dataset.recruitHero);return;}if(btn.dataset.exchangeLegend){exchangeLegendTokens(Number(btn.dataset.exchangeLegend));return;}if(btn.dataset.upgradeKungfu){upgradeKungfu(btn.dataset.upgradeKungfu);return;}if(btn.dataset.equipKungfu){equipKungfuRef(btn.dataset.equipKungfu);return;}if(btn.dataset.equipDivine){equipKungfuRef(`god:${btn.dataset.equipDivine}`);return;}if(btn.dataset.unequipSlot!==undefined){unequipSlot(btn.dataset.unequipSlot);return;}if(btn.dataset.fuseDivine){fuseDivine(btn.dataset.fuseDivine);return;}if(btn.dataset.weaponTheme!==undefined){state.weapons.theme=Number(btn.dataset.weaponTheme)||0;commit();return;}if(btn.dataset.equipWeapon){equipWeapon(btn.dataset.equipWeapon);return;}if(btn.dataset.unequipWeapon!==undefined){unequipWeapon(btn.dataset.unequipWeapon);return;}if(btn.dataset.strengthenWeapon){strengthenWeapon(btn.dataset.strengthenWeapon);return;}if(btn.dataset.breakthroughWeapon){breakthroughWeapon(btn.dataset.breakthroughWeapon);return;}if(btn.dataset.smeltWeapon){smeltWeapon(btn.dataset.smeltWeapon);return;}if(btn.dataset.buySoul){buySoulShards(btn.dataset.buySoul,Number(btn.dataset.soulTimes||1));return;}if(btn.dataset.choiceSoul){useChoiceSoulPack(btn.dataset.choiceSoul);return;}if(btn.dataset.synthSoul){synthSoul(btn.dataset.synthSoul);return;}if(btn.dataset.awakenHero){awakenHero(btn.dataset.awakenHero);return;}if(btn.dataset.buyVipGift!==undefined){buyVipGift(Number(btn.dataset.buyVipGift));return;}if(btn.dataset.buySpecial){buySpecialItem(btn.dataset.buySpecial);return;}if(btn.dataset.useSpecialPack){useSpecialChoicePack(btn.dataset.useSpecialPack);return;}if(btn.dataset.claimActivity){claimActivityReward(Number(btn.dataset.claimActivity));return;}if(btn.dataset.claimGrowth){claimGrowthTask(btn.dataset.claimGrowth);return;}if(btn.dataset.innerMedicine){useInnerMedicine(btn.dataset.innerMedicine);return;}if(btn.dataset.buyInner){buyInnerItem(btn.dataset.buyInner);return;}if(btn.dataset.recharge){recharge(Number(btn.dataset.recharge));return;}const action=btn.dataset.action;if(action==='chapter')challengeChapter();if(action==='quick')quickBattle();if(action==='tower')challengeTower();if(action==='ancientTomb')challengeAncientTomb();if(action==='ancientTombSpeed')speedAncientTomb();if(action==='meridian')unlockMeridianPoint();if(action==='wudao')advanceWudao();if(action==='buyWudaoPills')buyWudaoPills();if(action==='wudaoRechargePack')buyWudaoRechargePack();if(action==='drawKungfu1')drawKungfu(1);if(action==='drawKungfu5')drawKungfu(5);if(action==='assignInnerRoom')assignInnerRoom();if(action==='leaveInnerRoom')leaveInnerRoom();if(action==='innerBreakthrough')attemptInnerBreakthrough(false);if(action==='innerBreakthroughPill')attemptInnerBreakthrough(true);if(action==='buyWeaponIron')buyWeaponIron();if(action==='buyMeteorIron')buyMeteorIron();if(action==='forgeWeapon')forgeWeapon();if(action==='buyStamina')buyStamina();if(action==='moneyTree')moneyTree();if(action==='export')exportSave(state);if(action==='import')importInput.click();if(action==='reset'&&confirm('确定清空本地存档并重新开始？')){state=resetSave();selectedGrowthHero='player';selectedGrowthTab='meridian';commit();}});
pageEl.addEventListener('change',e=>{if(e.target.id==='growthHeroSelect'){selectedGrowthHero=e.target.value;renderGrowth();}});
document.querySelector('.bottom-nav').addEventListener('click',e=>{const btn=e.target.closest('[data-page]');if(!btn)return;currentPage=btn.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});});
battleDialog.addEventListener('click',e=>{if(e.target.closest('[data-close-dialog]'))battleDialog.close();});
importInput.addEventListener('change',e=>onImport(e.target.files?.[0]));
setInterval(()=>{const beforeStamina=state.player.stamina,beforeTick=Number(state.innerPower?.lastTick||0);recoverStamina(state);recoverInnerPower(state);const changed=state.player.stamina!==beforeStamina||Number(state.innerPower?.lastTick||0)!==beforeTick;if(changed){saveState(state);renderResources();if(currentPage==='growth'&&selectedGrowthTab==='innerPower')renderGrowth();}},30000);
window.addEventListener('beforeunload',()=>saveState(state));
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();